-- Nutrogan schema snapshot inferido desde filas live (2026-09-29T18:28:32.765Z)\n-- NO es DDL oficial de Postgres; columnas tipadas por muestra. Usar para documentar/reconstruir a mano.\n\ncreate table if not exists public.establecimientos (\n  id text,\n  nombre text,\n  ubicacion text,\n  created_at text,\n  geometria text,\n  ultimo_ndvi text,\n  fecha_ultimo_ndvi text,\n  ciudad text,\n  provincia text,\n  pin_location jsonb,\n  veterinario_telefono text,\n  ingeniero_telefono text,\n  emergencia_config jsonb,\n  owner_id text\n);\n\ncreate table if not exists public.lotes (\n  id text,\n  establecimiento_id text,\n  identificacion text,\n  categoria_zootecnica_id text,\n  potrero_actual_id text,\n  activo boolean,\n  created_at text,\n  objetivo text,\n  cantidad_animales bigint,\n  peso_ingreso_kg bigint\n);\n\ncreate table if not exists public.potreros (\n  id text,\n  establecimiento_id text,\n  nombre text,\n  superficie_ha numeric,\n  estado text,\n  disponibilidad_forraje_kg_ha text,\n  dias_descanso_optimo bigint,\n  fuente_agua_id text,\n  disponibilidad_forraje text,\n  ultimo_ndvi numeric,\n  geometria jsonb,\n  activo boolean,\n  fecha_ultimo_ndvi text,\n  ndvi_max text,\n  ndvi_min text,\n  area_geometria numeric,\n  tipo text,\n  descripcion text,\n  updated_at text,\n  snapshot_url text,\n  ciudad text,\n  provincia text,\n  ultimo_ndmi text,\n  fecha_ultimo_ndmi text\n);\n\ncreate table if not exists public.fuentes_de_agua (\n  id text,\n  establecimiento_id text,\n  nombre text,\n  tipo text,\n  potrero_id text,\n  geometria jsonb,\n  es_inteligente boolean,\n  ultimo_estado text,\n  activo boolean,\n  updated_at text\n);\n\ncreate table if not exists public.analisis_de_agua (\n  id text,\n  fuente_id text,\n  fecha_analisis text,\n  metodo text,\n  ph numeric,\n  solidos_totales bigint,\n  conductividad_electrica bigint,\n  dureza bigint,\n  nitratos bigint,\n  arsenico bigint,\n  observaciones text,\n  created_at text\n);\n\ncreate table if not exists public.registros_lluvia (\n  id text,\n  establecimiento_id text,\n  fecha text,\n  milimetros bigint,\n  observaciones text,\n  created_at text\n);\n\n-- dietas: empty (0 rows visible)\n-- dietas_items: empty (0 rows visible)\ncreate table if not exists public.alimentos (\n  id text,\n  establecimiento_id text,\n  nombre text,\n  precio_kg numeric,\n  stock_kg bigint\n);\n\ncreate table if not exists public.inventario_items (\n  id text,\n  establecimiento_id text,\n  nombre text,\n  categoria text,\n  stock_actual bigint,\n  unidad text,\n  precio_unitario bigint,\n  stock_minimo_alerta bigint,\n  activo boolean,\n  created_at text,\n  updated_at text\n);\n\ncreate table if not exists public.inventario_movimientos (\n  id bigint,\n  item_id text,\n  lote_id text,\n  fecha text,\n  tipo_movimiento text,\n  cantidad bigint,\n  costo_total bigint,\n  observaciones text\n);\n\ncreate table if not exists public.invitaciones_equipo (\n  id text,\n  email text,\n  rol text,\n  establecimiento_id text,\n  created_at text\n);\n\ncreate table if not exists public.miembros_establecimiento (\n  id text,\n  usuario_id text,\n  establecimiento_id text,\n  rol text,\n  created_at text\n);\n\ncreate table if not exists public.movimientos_de_lotes (\n  id text,\n  lote_id text,\n  potrero_id text,\n  fecha_entrada text,\n  fecha_salida text,\n  observaciones text\n);\n\ncreate table if not exists public.notificaciones_programadas (\n  id text,\n  establecimiento_id text,\n  created_by text,\n  titulo text,\n  mensaje text,\n  categoria text,\n  prioridad text,\n  fecha_programada text,\n  estado text,\n  estilos_email jsonb,\n  destinatarios_snapshot jsonb,\n  created_at text\n);\n\ncreate table if not exists public.perfiles_usuarios (\n  id text,\n  nombre_completo text,\n  rol text,\n  apellido text,\n  telefono text,\n  avatar_url text,\n  establecimiento_id text,\n  establecimiento_activo_id text,\n  email text,\n  direccion text,\n  config_notificaciones jsonb\n);\n\ncreate table if not exists public.evaluaciones (\n  id text,\n  fecha_evaluacion text,\n  peso_promedio_kg text,\n  condicion_corporal bigint,\n  observaciones text,\n  created_at text,\n  lote_id text\n);\n\ncreate table if not exists public.eventos_sanitarios (\n  id text,\n  fecha text,\n  tipo_evento text,\n  descripcion text,\n  lote_id text\n);\n\n-- eventos_reproductivos: empty (0 rows visible)\ncreate table if not exists public.consumos_de_dieta (\n  id text,\n  lote_id text,\n  dieta_id text,\n  alimento_id text,\n  fecha_inicio text,\n  fecha_fin text,\n  kg_animal_dia bigint,\n  costo_total_periodo bigint,\n  observaciones text\n);\n